  1→//! Local template loading from user and project directories.
  2→
  3→use crate::error::Result;
  4→use crate::registry::template::{Template, TemplateSource};
  5→use std::collections::HashMap;
  6→use std::fs;
  7→use std::path::{Path, PathBuf};
  8→
  9→/// Loader for local templates (user and project).
 10→#[derive(Debug, Clone)]
 11→pub struct LocalLoader {
 12→    templates: HashMap<String, (Template, TemplateSource)>,
 13→}
 14→
 15→impl LocalLoader {
 16→    /// Load templates from user and project directories.
 17→    pub fn new(project_root: Option<&Path>) -> Result<Self> {
 18→        let mut templates = HashMap::new();
 19→
 20→        // Load user templates (~/.bivvy/templates/)
 21→        if let Some(user_dir) = Self::user_templates_dir() {
 22→            Self::load_from_dir(&user_dir, TemplateSource::User, &mut templates)?;
 23→        }
 24→
 25→        // Load project templates (.bivvy/templates/)
 26→        if let Some(root) = project_root {
 27→            let project_dir = root.join(".bivvy").join("templates");
 28→            Self::load_from_dir(&project_dir, TemplateSource::Project, &mut templates)?;
 29→        }
 30→
 31→        Ok(Self { templates })
 32→    }
 33→
 34→    /// Get user templates directory.
 35→    fn user_templates_dir() -> Option<PathBuf> {
 36→        dirs::home_dir().map(|h| h.join(".bivvy").join("templates"))
 37→    }
 38→
 39→    /// Load templates from a directory (recursively).
 40→    fn load_from_dir(
 41→        dir: &Path,
 42→        source: TemplateSource,
 43→        templates: &mut HashMap<String, (Template, TemplateSource)>,
 44→    ) -> Result<()> {
 45→        if !dir.exists() {
 46→            return Ok(());
 47→        }
 48→
 49→        // Load from steps/ subdirectory
 50→        let steps_dir = dir.join("steps");
 51→        if steps_dir.exists() {
 52→            Self::load_templates_recursive(&steps_dir, source, templates)?;
 53→        }
 54→
 55→        Ok(())
 56→    }
 57→
 58→    fn load_templates_recursive(
 59→        dir: &Path,
 60→        source: TemplateSource,
 61→        templates: &mut HashMap<String, (Template, TemplateSource)>,
 62→    ) -> Result<()> {
 63→        if !dir.is_dir() {
 64→            return Ok(());
 65→        }
 66→
 67→        for entry in fs::read_dir(dir)? {
 68→            let entry = entry?;
 69→            let path = entry.path();
 70→
 71→            if path.is_dir() {
 72→                Self::load_templates_recursive(&path, source, templates)?;
 73→            } else if path
 74→                .extension()
 75→                .map(|e| e == "yml" || e == "yaml")
 76→                .unwrap_or(false)
 77→            {
 78→                let content = fs::read_to_string(&path)?;
 79→                let template: Template = serde_yaml::from_str(&content).map_err(|e| {
 80→                    crate::error::BivvyError::ConfigParseError {
 81→                        path: path.clone(),
 82→                        message: e.to_string(),
 83→                    }
 84→                })?;
 85→
 86→                // Project templates override user templates
 87→                if source == TemplateSource::Project || !templates.contains_key(&template.name) {
 88→                    templates.insert(template.name.clone(), (template, source));
 89→                }
 90→            }
 91→        }
 92→
 93→        Ok(())
 94→    }
 95→
 96→    /// Get a template by name.
 97→    pub fn get(&self, name: &str) -> Option<&Template> {
 98→        self.templates.get(name).map(|(t, _)| t)
 99→    }
100→
101→    /// Get a template with its source.
102→    pub fn get_with_source(&self, name: &str) -> Option<(&Template, TemplateSource)> {
103→        self.templates.get(name).map(|(t, s)| (t, *s))
104→    }
105→
106→    /// Get all template names.
107→    pub fn template_names(&self) -> Vec<&str> {
108→        self.templates.keys().map(|s| s.as_str()).collect()
109→    }
110→
111→    /// Check if a template exists.
112→    pub fn has(&self, name: &str) -> bool {
113→        self.templates.contains_key(name)
114→    }
115→}
