256→/// Scrub sensitive content from text before sending externally.
257→///
258→/// Masks:
259→/// - Environment variable values matching secret patterns
260→/// - Home directory paths
261→/// - Usernames in paths
262→pub fn scrub_payload(text: &str) -> String {
263→    if text.is_empty() {
264→        return String::new();
265→    }
266→
267→    let mut masker = OutputMasker::new();
268→    let matcher = SecretMatcher::with_builtins();
269→
270→    // Collect secret env var values
271→    for (key, value) in std::env::vars() {
272→        if matcher.is_secret(&key) && !value.is_empty() {
273→            masker.add_secret(value);
274→        }
275→    }
276→
277→    let mut result = masker.mask(text);
278→
279→    // Replace home directory
280→    if let Some(home) = dirs::home_dir() {
281→        let home_str = home.display().to_string();
282→        if !home_str.is_empty() {
283→            result = result.replace(&home_str, "~");
284→        }
285→    }
286→
287→    // Replace username in paths (e.g., /home/username/ or /Users/username/)
288→    if let Some(home) = dirs::home_dir() {
289→        if let Some(username) = home.file_name() {
290→            let username_str = username.to_string_lossy();
291→            // Only replace in path-like contexts
292→            let patterns = [
293→                format!("/home/{}/", username_str),
294→                format!("/Users/{}/", username_str),
295→                format!("\\Users\\{}\\", username_str),
296→                format!("/home/{}", username_str),
297→                format!("/Users/{}", username_str),
298→            ];
299→            for pattern in &patterns {
300→                let replacement = pattern.replace(&*username_str, "<user>");
301→                result = result.replace(pattern, &replacement);
302→            }
303→        }
304→    }
305→
306→    result
307→}
